class BENCHMARK_EXPORT BENCHMARK_INTERNAL_CACHELINE_ALIGNED State {
 public:
  struct StateIterator;
  friend struct StateIterator;
  inline BENCHMARK_ALWAYS_INLINE StateIterator begin();
  inline BENCHMARK_ALWAYS_INLINE StateIterator end();
  inline bool KeepRunning();
  inline bool KeepRunningBatch(IterationCount n);
  void PauseTiming();
  void ResumeTiming();
  void SkipWithMessage(const std::string& msg);
  void SkipWithError(const std::string& msg);
  bool skipped() const { return internal::NotSkipped != skipped_; }
  bool error_occurred() const { return internal::SkippedWithError == skipped_; }
  void SetIterationTime(double seconds);
  BENCHMARK_ALWAYS_INLINE void SetBytesProcessed(int64_t bytes) {
    counters["bytes_per_second"] =
        Counter(static_cast<double>(bytes), Counter::kIsRate, Counter::kIs1024);
  }
  BENCHMARK_ALWAYS_INLINE int64_t bytes_processed() const {
    if (counters.find("bytes_per_second") != counters.end())
      return static_cast<int64_t>(counters.at("bytes_per_second"));
    return 0;
  }
  BENCHMARK_ALWAYS_INLINE void SetComplexityN(ComplexityN complexity_n) {
    complexity_n_ = complexity_n;
  }
  BENCHMARK_ALWAYS_INLINE ComplexityN complexity_length_n() const { return complexity_n_; }
  BENCHMARK_ALWAYS_INLINE void SetItemsProcessed(int64_t items) {
    counters["items_per_second"] =
        Counter(static_cast<double>(items), benchmark::Counter::kIsRate);
  }
  BENCHMARK_ALWAYS_INLINE int64_t items_processed() const {
    if (counters.find("items_per_second") != counters.end())
      return static_cast<int64_t>(counters.at("items_per_second"));
    return 0;
  }
  void SetLabel(const std::string& label);
  BENCHMARK_ALWAYS_INLINE int64_t range(std::size_t pos = 0) const {
    assert(range_.size() > pos);
    return range_[pos];
  }
  BENCHMARK_DEPRECATED_MSG("use 'range(0)' instead") int64_t range_x() const { return range(0); }
  BENCHMARK_DEPRECATED_MSG("use 'range(1)' instead") int64_t range_y() const { return range(1); }
  BENCHMARK_ALWAYS_INLINE int threads() const { return threads_; }
  BENCHMARK_ALWAYS_INLINE int thread_index() const { return thread_index_; }
  BENCHMARK_ALWAYS_INLINE IterationCount iterations() const {
    if (BENCHMARK_BUILTIN_EXPECT(!started_, false)) {
      return 0;
    }
    return max_iterations - total_iterations_ + batch_leftover_;
  }
  BENCHMARK_ALWAYS_INLINE std::string name() const { return name_; }
  size_t range_size() const { return range_.size(); }
 private:
  IterationCount total_iterations_;
  IterationCount batch_leftover_;
 public:
  const IterationCount max_iterations;
 private:
  bool started_;
  bool finished_;
  internal::Skipped skipped_;
  std::vector<int64_t> range_;
  ComplexityN complexity_n_;
 public:
  UserCounters counters;
 private:
  State(std::string name, IterationCount max_iters,
        const std::vector<int64_t>& ranges, int thread_i, int n_threads,
        internal::ThreadTimer* timer, internal::ThreadManager* manager,
        internal::PerfCountersMeasurement* perf_counters_measurement,
        ProfilerManager* profiler_manager);
  void StartKeepRunning();
  inline bool KeepRunningInternal(IterationCount n, bool is_batch);
  void FinishKeepRunning();
  const std::string name_;
  const int thread_index_;
  const int threads_;
  internal::ThreadTimer* const timer_;
  internal::ThreadManager* const manager_;
  internal::PerfCountersMeasurement* const perf_counters_measurement_;
  ProfilerManager* const profiler_manager_;
  friend class internal::BenchmarkInstance;
};

struct State::StateIterator {
  struct BENCHMARK_UNUSED Value {};
  typedef std::forward_iterator_tag iterator_category;
  typedef Value value_type;
  typedef Value reference;
  typedef Value pointer;
  typedef std::ptrdiff_t difference_type;
 private:
  friend class State;
  BENCHMARK_ALWAYS_INLINE StateIterator() : cached_(0), parent_() {}
  BENCHMARK_ALWAYS_INLINE explicit StateIterator(State* st)
      : cached_(st->skipped() ? 0 : st->max_iterations), parent_(st) {}
 public:
  BENCHMARK_ALWAYS_INLINE Value operator*() const { return Value(); }
  BENCHMARK_ALWAYS_INLINE StateIterator& operator++() { assert(cached_ > 0); --cached_; return *this; }
  BENCHMARK_ALWAYS_INLINE bool operator!=(StateIterator const&) const {
    if (BENCHMARK_BUILTIN_EXPECT(cached_ != 0, true)) return true;
    parent_->FinishKeepRunning();
    return false;
  }
 private:
  IterationCount cached_;
  State* const parent_;
};

