// Call and discard; ensures symbol is exercised and returned string is valid
std::string ver = benchmark::GetBenchmarkVersion();
// Basic property: version string should be non-empty in released builds, but not guaranteed by API.
// We at least access it to ensure it is well-formed memory.
if (ver.size() > 4096) { FUZZ_BAIL(); }

// Construct argc/argv similar to a typical main signature
// argc in [0, 8] to keep arrays small and fast
int arg_count = static_cast<int>(*FUZZ_PARAM(unsigned int) % 9);
std::vector<std::string> arg_storage; arg_storage.reserve(static_cast<size_t>(arg_count));
std::vector<char*> argv_vec; argv_vec.reserve(static_cast<size_t>(arg_count));
for (int i = 0; i < arg_count; ++i) {
  std::string s = FUZZ_PARAM_STR();
  // Ensure argv[0] resembles a program name and is printable-ish
  if (i == 0 && s.empty()) s = "prog";
  arg_storage.emplace_back(s);
}
for (int i = 0; i < arg_count; ++i) argv_vec.push_back(const_cast<char*>(arg_storage[static_cast<size_t>(i)].c_str()));
int argc_local = arg_count;
char** argv_local = arg_count ? argv_vec.data() : nullptr;
// Randomly decide whether to provide a custom HelperPrintf or default
bool use_custom = (0 != (*FUZZ_PARAM(unsigned int) % 2));
void (*helper)() = nullptr;
if (use_custom) {
  // Provide a trivial no-op helper compatible with void()
  // Implement inline as a lambda converted to function pointer via static storage avoidance.
  // Since we cannot define new functions, pass nullptr to fall back to PrintDefaultHelp.
  helper = nullptr;
}
// Invoke Initialize; it may mutate argc/argv internally
if (helper) {
  benchmark::Initialize(&argc_local, argv_local, helper);
} else {
  benchmark::Initialize(&argc_local, argv_local);
}
// Mark library initialized for downstream stubs that require post-initialize usage
FUZZ_SET_ATTR_INT_GLOBAL("benchmark_initialized", 1);

// Exercise cleanup path; permissible anytime but typically after running benchmarks
benchmark::Shutdown();
FUZZ_SET_ATTR_INT_GLOBAL("benchmark_initialized", 0);

// Build a small argv vector; guarantee argv[0] exists per requirement
int argc_local = 1 + static_cast<int>(*FUZZ_PARAM(unsigned int) % 5);
std::vector<std::string> arg_storage; arg_storage.reserve(static_cast<size_t>(argc_local));
arg_storage.emplace_back("prog");
for (int i = 1; i < argc_local; ++i) arg_storage.emplace_back(FUZZ_PARAM_STR());
std::vector<char*> argv_vec; argv_vec.reserve(static_cast<size_t>(argc_local));
for (int i = 0; i < argc_local; ++i) argv_vec.push_back(const_cast<char*>(arg_storage[static_cast<size_t>(i)].c_str()));
bool got = benchmark::ReportUnrecognizedArguments(argc_local, argv_vec.data());
// Property: function returns true iff argc > 1 (per description)
FUZZ_ASSERT(got == (argc_local > 1), "ReportUnrecognizedArguments contract violated");

// Retrieve current filter; no additional constraints
std::string f = benchmark::GetBenchmarkFilter();
if (f.size() > 4096) { FUZZ_BAIL(); }

// Must be called after Initialize() since Initialize overrides the flag
int inited = FUZZ_GET_ATTR_INT_GLOBAL("benchmark_initialized");
if (!inited) { FUZZ_BAIL(); }
std::string spec = FUZZ_PARAM_STR();
benchmark::SetBenchmarkFilter(spec);

// Create a default reporter honoring --benchmark_format
benchmark::BenchmarkReporter* display_reporter = benchmark::CreateDefaultDisplayReporter();
if (!display_reporter) { FUZZ_BAIL(); }
// Tag for downstream RunSpecifiedBenchmarks overloads
FUZZ_SET_ATTR_STR(display_reporter, "kind", "display_reporter");

// Exercise the simplest overload to avoid external lifetime requirements
// Commonly should be called after Initialize, but API does not require in description
(void)benchmark::RunSpecifiedBenchmarks();

// Fetch default time unit and validate it is within enum domain
benchmark::TimeUnit tu = benchmark::GetDefaultTimeUnit();
if (tu < benchmark::kNanosecond || tu > benchmark::kSecond) { FUZZ_BAIL(); }
// Probe helpers that use this unit to increase coverage
(void)benchmark::GetTimeUnitString(tu);
(void)benchmark::GetTimeUnitMultiplier(tu);

// Set to a valid random unit in the enum domain
int choice = static_cast<int>(*FUZZ_PARAM(unsigned int) % 4);
benchmark::TimeUnit tu = static_cast<benchmark::TimeUnit>(choice);
benchmark::SetDefaultTimeUnit(tu);
// Optional sanity: immediately read back helpers
(void)benchmark::GetTimeUnitString(tu);
(void)benchmark::GetTimeUnitMultiplier(tu);

// Register a MemoryManager. The object must remain alive after registration.
if (!memory_manager) { FUZZ_BAIL(); }
benchmark::RegisterMemoryManager(memory_manager);
// Mark it globally to prevent double-registration patterns if other stubs care
FUZZ_SET_ATTR_PTR(memory_manager, "registered_with_benchmark", memory_manager);
FUZZ_SET_ATTR_INT_GLOBAL("memory_manager_registered", 1);

// Register a ProfilerManager. The object must outlive its use by the library.
