import random
from typing import List

# Generator for Google Benchmark --benchmark_filter style regex strings.
# Aim: produce valid, interesting regex patterns that match different name classes.
# Returned as bytes for FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME consumption.

_MAX_LEN = 1024

_BENCH_NAME_PARTS = [
    "BM_Sort", "BM_HashMap", "BM_JSON_Parse", "BM_EncodeUTF8", "BM_MatrixMul",
    "BM_IO_Read", "BM_IO_Write", "BM_FFT", "BM_Compress", "BM_Regex",
]

# Common regex atoms tuned to match benchmark names, arguments, threads, etc.
_SIMPLE_ATOMS = [
    r".*", r".+", r"^", r"$", r"^BM_", r"BM_", r".*/real_time", r".*/manual_time",
    r".*/threads:\\d+", r".*/repeats:\\d+", r".*/items_per_second", r".*/bytes_per_second",
    r"[A-Za-z0-9_]+", r"BM_[A-Za-z]+", r"BM_[A-Za-z]+_[A-Za-z]+", r"[A-Z][A-Za-z0-9_]*",
]

# Character classes that are generally safe in common regex dialects.
_CHAR_CLASSES = [r"[A-Za-z]", r"[A-Za-z0-9_]", r"[A-Z_]+", r"[a-z]+", r"[0-9]+", r"[^/]+"]

_QUANTIFIERS = ["", "?", "+", "*", "{1,3}", "{2,}", "{0,2}"]

_GROUP_WRAPPERS = [
    ("", ""), ("(", ")"), ("(?:", ")"), ("(?=", ")"), ("(?!", ")"),
]

_ALTERNATIONS_BASE = [
    r"/threads:\\d+", r"/repeats:\\d+", r"/real_time", r"/manual_time", r"/cpu_time",
    r"/BigO", r"/RMS", r"/complexity:.+", r"/args:.+",
]

_SPECIAL_ESCAPES = [r"\\d", r"\\w", r"\\W", r"\\s", r"\\S", r"\\b", r"\\B"]

# Pre-crafted useful filters frequently used by users.
_CANONICAL_FILTERS = [
    r"^BM_.*",            # any benchmark
    r"^BM_Sort.*",        # specific family
    r".*(IO|JSON).*",     # alternation on names
    r".*/(real_time|manual_time)$",  # time-mode tagged
    r".*/threads:\\d+$", # thread-suffixed
    r"^(?!.*Slow).*$",     # exclude Slow
    r"^(?=.*Matrix).*$",   # require Matrix
    r"^$",                # empty filter (matches nothing)
    r".*",                # match all
    r"^BM_[A-Za-z0-9_]+/(?:[0-9]+x[0-9]+|[0-9]+)$",  # shaped arg suffixes
]

def _maybe(rng: random.Random, p: float) -> bool:
    return rng.random() < p

def _random_literal_name(rng: random.Random) -> str:
    base = rng.choice(_BENCH_NAME_PARTS)
    # Optionally attach synthetic argument encodings resembling Google Benchmark arg suffixes
    pieces = [base]
    if _maybe(rng, 0.6):
        mode = rng.choice(["/real_time", "/manual_time", "", ""])  # bias to no mode
        if mode:
            pieces.append(mode)
    if _maybe(rng, 0.6):
        if _maybe(rng, 0.5):
            pieces.append(f"/{rng.randint(1, 1024)}")
        else:
            pieces.append(f"/{rng.randint(2,16)}x{rng.randint(2,16)}")
    if _maybe(rng, 0.4):
        pieces.append(f"/threads:{rng.randint(1,64)}")
    if _maybe(rng, 0.3):
        pieces.append(f"/repeats:{rng.randint(1,10)}")
    return "".join(pieces)

def _random_atom(rng: random.Random) -> str:
    choice_pool = _SIMPLE_ATOMS + _CHAR_CLASSES + _SPECIAL_ESCAPES
    atom = rng.choice(choice_pool)
    return atom

def _random_group(rng: random.Random) -> str:
    left, right = rng.choice(_GROUP_WRAPPERS)
    core = _random_atom(rng)
    if _maybe(rng, 0.4):
        core += rng.choice(_QUANTIFIERS)
    return f"{left}{core}{right}"

def _random_alternation(rng: random.Random) -> str:
    # Build an alternation of 2-4 choices
    n = rng.randint(2, 4)
    choices: List[str] = []
    for _ in range(n):
        if _maybe(rng, 0.5):
            choices.append(_random_group(rng))
        else:
            choices.append(rng.choice(_ALTERNATIONS_BASE))
    return "(" + "|".join(choices) + ")"

def _build_regex(rng: random.Random) -> str:
    # Mix anchors, literals, classes, alternations, and quantifiers
    parts: List[str] = []
    if _maybe(rng, 0.7):
        parts.append("^")
    segment_count = rng.randint(1, 5)
    for _ in range(segment_count):
        kind = rng.random()
        if kind < 0.25:
            parts.append(_random_literal_name(rng))
        elif kind < 0.5:
            parts.append(_random_group(rng))
        elif kind < 0.75:
            parts.append(_random_alternation(rng))
        else:
            parts.append(_random_atom(rng))
        if _maybe(rng, 0.4):
            parts.append(".*")
    if _maybe(rng, 0.6):
        parts.append("$")
    # Occasionally simplify to canonical filters
    if _maybe(rng, 0.25):
        parts = [rng.choice(_CANONICAL_FILTERS)]
    s = "".join(parts)
    # Ensure non-empty and under length
    if not s:
        s = ".*"
    return s[:_MAX_LEN]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = rng.random()
    if mode < 0.20:
        # Return a canonical useful filter
        s = rng.choice(_CANONICAL_FILTERS)
    elif mode < 0.40:
        # Return a literal exact name (escaped) to match a single benchmark
        name = _random_literal_name(rng)
        # Escape regex metacharacters in the literal so it matches exactly
        esc: List[str] = []
        meta = ".^$|?*+()[]{}:"
        for ch in name:
            if ch in meta or ch == "\\":
                esc.append("\\" + ch)
            else:
                esc.append(ch)
        s = "^" + "".join(esc) + "$"
    else:
        s = _build_regex(rng)
    s = s[:_MAX_LEN]
    return s.encode("utf-8")

import random
import string
from typing import List, Tuple

# This generator targets fuzzer stubs that consume arbitrary strings for:
# - benchmark::AddCustomContext(key, value)
# - benchmark::RegisterBenchmark(name, lambda)
# - benchmark::RegisterBenchmark(name, lambda, int, payload)
# Produces valid UTF-8 strings packaged as length-prefixed segments so
# multiple FUZZ_PARAM_STR() calls can read sequentially.

MAX_TOTAL = 4096

BENCH_NAME_TEMPLATES: List[str] = [
    "BM_{word}",
    "BM_{word}/{num}",
    "BM_{word}/{num}x{num}",
    # Avoid unknown placeholders; only use {word} and {num}
    "BM_{word}/{word}/{num}",
    "BM_{word}/threads:{num}",
    "BM_{word}/real_time",
    "BM_{word}/manual_time",
    "BM_{word}/bytes_per_second",
    "BM_{word}/items_per_second",
    "BM_{word}_Complexity_{num}",
    "BM_{word}/arg/{num}",
]

WORDS = [
    "Fuzz", "Sort", "Hash", "Parse", "IO", "Math", "JSON", "CSV",
    "HTTP", "Crypto", "Graph", "Regex", "Image", "Audio", "Video",
]

UNICODE_SNIPPETS = [
    "α", "β", "γ", "漢字", "✓", "é", "№", "–", "—", "•",
]

CONTEXT_KEYS = [
    "os", "arch", "compiler", "build_type", "commit", "branch",
    "dataset", "mode", "feature_flag", "env", "notes",
]

CONTEXT_VALUES = [
    "linux", "windows", "darwin", "amd64", "arm64", "clang-17", "gcc-13",
    "debug", "release", "on", "off", "true", "false", "exp", "prod",
]

SAFE_ASCII = string.ascii_letters + string.digits + "_-:.#/"


def _rand_word(rng: random.Random, min_len: int = 3, max_len: int = 12) -> str:
    if rng.random() < 0.25:
        base = rng.choice(WORDS) + rng.choice(UNICODE_SNIPPETS)
    else:
        base = rng.choice(WORDS)
    tail_len = rng.randint(min_len, max_len)
    tail = ''.join(rng.choice(string.ascii_letters) for _ in range(tail_len))
    return base + tail


def _rand_num(rng: random.Random, magnitude_choices=(1, 10, 100, 1000, 100000)) -> int:
    choices = [1, 2, 3, 4, 5, 8, 10, 16, 32, 64, 100, 128, 256, 512, 1000, 4096, 8192]
    if rng.random() < 0.6:
        return rng.choice(choices)
    mag = rng.choice(magnitude_choices)
    return rng.randint(1, mag)


def _make_bench_name(rng: random.Random) -> str:
    tmpl = rng.choice(BENCH_NAME_TEMPLATES)
    name = tmpl.format(word=_rand_word(rng), num=_rand_num(rng))
    if rng.random() < 0.3:
        name = "Namespace::" + name
    if rng.random() < 0.3:
        name += "/lbl:" + ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(3, 8)))
    return name[:200]


def _make_context_pair(rng: random.Random) -> Tuple[str, str]:
    if rng.random() < 0.6:
        key = rng.choice(CONTEXT_KEYS)
    else:
        key = _rand_word(rng, 2, 6).lower()
    if rng.random() < 0.6:
        val = rng.choice(CONTEXT_VALUES)
    else:
        parts: List[str] = []
        parts.append(_rand_word(rng, 2, 5))
        if rng.random() < 0.5:
            parts.append(str(_rand_num(rng)))
        if rng.random() < 0.3:
            parts.append(rng.choice(UNICODE_SNIPPETS))
        val = '-'.join(parts)
    if rng.random() < 0.2:
        val = f"{val},flag={rng.choice(['on','off','auto'])}"
    return key[:100], val[:200]


def _random_payload(rng: random.Random, max_len: int) -> str:
    pieces: List[str] = []
    for _ in range(rng.randint(1, 5)):
        pieces.append(_rand_word(rng, 2, 8))
    for _ in range(rng.randint(0, 3)):
        pieces.append(str(_rand_num(rng)))
    if rng.random() < 0.4:
        pieces.append(rng.choice(UNICODE_SNIPPETS))
    s = ' '.join(pieces)
    if rng.random() < 0.5:
        seg = ''.join(rng.choice(SAFE_ASCII) for _ in range(rng.randint(5, 20)))
        s += '|' + seg
    return s[:max_len]


def _encode_chunks(chunks: List[bytes]) -> bytes:
    out = b""
    for c in chunks:
        out += c
    return out[:MAX_TOTAL]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    key, val = _make_context_pair(rng)

    name1 = _make_bench_name(rng) or "BM_Fuzz1"
    name2 = _make_bench_name(rng) or "BM_Fuzz2"

    payload = _random_payload(rng, 512)

    if rng.random() < 0.2:
        name1 += ",param=" + str(_rand_num(rng))
    if rng.random() < 0.2:
        name2 += "\n" + _make_bench_name(rng)
    if rng.random() < 0.2:
        payload += "\nmeta:" + _random_payload(rng, 64)

    def pack_str(s: str) -> bytes:
        b = s.encode('utf-8', errors='strict')
        l = len(b)
        return l.to_bytes(4, 'little') + b

    chunks: List[bytes] = [
        pack_str(key),
        pack_str(val),
        pack_str(name1),
        pack_str(name2),
        pack_str(payload),
    ]

    return _encode_chunks(chunks)
